 interface Work {void run()throws Exception;}void cryptoWork(Work w){final Object owner=actionTicket();if(busy){toast(t("Please wait.","കാത്തിരിക്കുക."));return;}busy=true;ProgressDialog p=new ProgressDialog(this);p.setMessage(t("Working on your device.","ഫോണിൽ തയ്യാറാക്കുന്നു."));p.setCancelable(false);p.show();new Thread(()->{try{w.run();}catch(Exception e){postAction(owner,()->toast(t("Could not open or create the backup. Check the passphrase and file. Existing records were not changed.","ബാക്കപ്പ് തുറക്കാനോ തയ്യാറാക്കാനോ കഴിഞ്ഞില്ല. പാസ്‌ഫ്രെയ്സും ഫയലും പരിശോധിക്കുക. നിലവിലെ കണക്കുകൾ മാറിയിട്ടില്ല.")));}finally{runOnUiThread(()->{busy=false;if(!isDestroyed()&&p.isShowing())p.dismiss();});}}).start();}
